config.performance-measurement-objects:
{% if config.rx_window_objects %}    {{ config.rx_window_interval | default(60) }}
{% endif %}{% if config.transceiver_objects %}    {{ config.transceiver_interval | default(60) }}
{% endif %}{% if config.tx_objects %}    {{ config.tx_interval | default(60) }}
{% endif %}{% if config.epe_objects %}    {{ config.epe_interval | default(60) }}
{% endif %}    {{ config.notification_interval | default(60) }}
{% for measurement_object in config.rx_window_objects %}    
        {{ measurement_object }}
        {{ config.pm_active }}
        RU
        COUNT

{% endfor %}{% for measurement_object in config.transceiver_objects %}    
        {{ measurement_object }}
        {{ config.pm_active }}
        MINIMUM
        MAXIMUM
        LATEST
        PORT_NUMBER

{% endfor %}{% for measurement_object in config.tx_objects %}    
        {{ measurement_object }}
        {{ config.pm_active }}
        RU
        COUNT

{% endfor %}{% for measurement_object in config.epe_objects %}    
        {{ measurement_object }}
        {{ config.pm_active }}
        MINIMUM
        MAXIMUM
        AVERAGE

{% endfor %}
